mapper.select:
SELECT f.id, f.code, f.user_id, f.type, f.content, f.contact, f.status,
       f.handle_remark, f.handle_by, f.handle_time, f.gmt_create, f.gmt_modify,
       u.name AS user_name, u.doorplate AS user_doorplate, u.mobile AS user_mobile
FROM feedback f
LEFT JOIN user u ON f.user_id = u.id


        AND f.status = #{status}


        AND f.type = #{type}


        AND f.user_id = #{userId}


        AND (f.content LIKE CONCAT('%', #{keyword}, '%')
          OR f.contact LIKE CONCAT('%', #{keyword}, '%')
          OR u.name LIKE CONCAT('%', #{keyword}, '%'))


        AND f.gmt_create >= #{startTime}


        AND f.gmt_create <= #{endTime}


ORDER BY f.gmt_create DESC

SELECT COUNT(*) FROM feedback
WHERE user_id = #{userId}
  AND gmt_create >= DATE_SUB(NOW(), INTERVAL #{hours} HOUR)

SELECT COUNT(*) FROM images
WHERE id IN

    #{imageId}

SELECT fi.feedback_code AS marketCode, fi.image_id AS id, f.url FROM feedback_images fi LEFT JOIN images f ON fi.image_id = f.id WHERE fi.feedback_code IN
#{code}
ORDER BY fi.create_time ASC
